(function($){"use strict";class ShippingCalculator{constructor(container,options={}){this.container=$(container);this.options=$.extend({productId:0,quantity:1,ajaxUrl:"",nonce:"",context:"",i18n:{}},options);if(typeof gstoreShippingCalculator!=="undefined"){this.options=$.extend(this.options,gstoreShippingCalculator)}this.lastDestination=null;this.init()}init(){this.cepInput=this.container.find(".gstore-shipping-calculator__cep");this.calculateBtn=this.container.find(".gstore-shipping-calculator__button");this.resultContainer=this.container.find(".gstore-shipping-calculator__result");this.errorContainer=this.container.find(".gstore-shipping-calculator__error");this.bindEvents()}bindEvents(){const self=this;this.cepInput.on("input",function(){let value=$(this).val().replace(/\D/g,"");if(value.length>8)value=value.slice(0,8);if(value.length>5){value=value.replace(/(\d{5})(\d{1,3})/,"$1-$2")}$(this).val(value)});this.calculateBtn.on("click",function(e){e.preventDefault();self.calculate()});this.cepInput.on("keypress",function(e){if(e.which===13){e.preventDefault();self.calculate()}});this.cepInput.on("input",function(){if(self.resultContainer.hasClass("is-visible")){self.clearResult()}})}validateCep(cep){const cleanCep=cep.replace(/\D/g,"");return cleanCep.length===8}resolveAjaxUrl(){if(this.options.ajaxUrl){return this.options.ajaxUrl}if(typeof gstoreShippingCalculator!=="undefined"&&gstoreShippingCalculator.ajaxUrl){return gstoreShippingCalculator.ajaxUrl}if(typeof wc_checkout_params!=="undefined"&&wc_checkout_params.ajax_url){return wc_checkout_params.ajax_url}return"/wp-admin/admin-ajax.php"}resolveContext(){const context=this.container.data("gstoreShippingContext")||this.container.attr("data-gstore-shipping-context")||this.options.context||"";if(context){return String(context)}return $("body").hasClass("single-product")?"single_product":""}resolveProductId(){const scopedProductId=parseInt(this.container.data("productId")||this.container.attr("data-product-id")||0,10);if(scopedProductId>0){return scopedProductId}const productId=parseInt(this.options.productId||0,10);return productId>0?productId:0}resolveQuantity(){const $scope=this.container.closest(".Gstore-single-product__summary-card, .summary, .product");const $searchScope=$scope.length?$scope:$(document);const $quantityInput=$searchScope.find('form.cart input[name="quantity"], form.cart .quantity input').first();if($quantityInput.length){const qty=parseInt($quantityInput.val(),10);if(qty>0){return qty}}const quantity=parseInt(this.options.quantity||1,10);return quantity>0?quantity:1}escapeHtml(value){return String(value||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;")}calculate(){const cep=this.cepInput.val().trim();const context=this.resolveContext();if(!this.validateCep(cep)){this.showError(this.options.i18n.invalidCep||"CEP inválido. Por favor, informe um CEP válido com 8 dígitos.");return}this.clearError();this.clearResult();this.setLoading(true);const data={action:"gstore_calculate_shipping",nonce:this.options.nonce,postcode:cep.replace(/\D/g,""),product_id:this.resolveProductId(),quantity:this.resolveQuantity(),calculation_context:context,isolated_product:context==="single_product"?1:0};$.ajax({url:this.resolveAjaxUrl(),type:"POST",data:data,dataType:"json",success:response=>{this.setLoading(false);if(response.success&&response.data){this.lastDestination=response.data.destination||null;this.showResult(response.data)}else{const message=response.data&&response.data.message?response.data.message:this.options.i18n.error||"Erro ao calcular frete. Tente novamente.";this.showError(message);this.lastDestination=null}},error:()=>{this.setLoading(false);this.showError(this.options.i18n.error||"Erro ao calcular frete. Tente novamente.");this.lastDestination=null}})}setLoading(loading){if(loading){this.calculateBtn.prop("disabled",true);this.calculateBtn.html('<i class="fa-solid fa-spinner fa-spin" aria-hidden="true"></i> '+(this.options.i18n.calculating||"Calculando..."))}else{this.calculateBtn.prop("disabled",false);this.calculateBtn.html('<i class="fa-solid fa-truck" aria-hidden="true"></i> '+(this.options.i18n.calculate||"Calcular frete"))}}showResult(data){const i18n=this.options.i18n;let rates=Array.isArray(data.rates)?data.rates:[];const destination=data.destination||{};const city=destination.city?String(destination.city).trim():"";const state=destination.state?String(destination.state).trim():"";const destinationLabel=city&&state?`${city}/${state}`:city||state;if(!rates.length&&data.cost_formatted){rates=[{label:i18n.frete||"Frete",cost_formatted:data.cost_formatted,mode:data.mode||"land"}]}if(!rates.length){this.showError(this.options.i18n.error||"Erro ao calcular frete. Tente novamente.");return}const ratesHtml=rates.map(rate=>{const label=rate.label||"";const mode=(rate.mode||"").toLowerCase();let labelText=label?label:(rate.mode||"").toLowerCase()==="air"?"Frete Aéreo":(rate.mode||"").toLowerCase()==="pickup"?"Retirada na loja":"Frete Terrestre";if(!label&&mode==="other"){labelText="Outros"}const hasQuoteNotice=rate.quote_value_enabled===false||String(rate.quote_notice_html||rate.cost_formatted||"").indexOf("gstore-shipping-quote-notice")!==-1;const costHtml=hasQuoteNotice?rate.quote_notice_html||rate.cost_formatted||`<span class="gstore-shipping-quote-notice">${this.escapeHtml(rate.quote_notice_message||"")}</span>`:mode==="other"?"-":rate.cost_formatted||"-";return`\n\t\t\t\t\t<div class="gstore-shipping-calculator__result-row${hasQuoteNotice?" gstore-shipping-calculator__result-row--quote-notice":""}">\n\t\t\t\t\t\t<span class="gstore-shipping-calculator__result-label">\n\t\t\t\t\t\t\t<i class="fa-solid fa-truck" aria-hidden="true"></i>\n\t\t\t\t\t\t\t${labelText}:\n\t\t\t\t\t\t</span>\n\t\t\t\t\t\t<strong class="gstore-shipping-calculator__result-value">${costHtml||"-"}</strong>\n\t\t\t\t\t</div>\n\t\t\t\t`}).join("");const html=`\n\t\t\t\t<div class="gstore-shipping-calculator__result-content">\n\t\t\t\t\t${ratesHtml}\n\t\t\t\t\t<div class="gstore-shipping-calculator__result-row">\n\t\t\t\t\t\t<span class="gstore-shipping-calculator__result-label">\n\t\t\t\t\t\t\t<i class="fa-solid fa-map-marker-alt" aria-hidden="true"></i>\n\t\t\t\t\t\t\t${i18n.destination||"Destino"}:\n\t\t\t\t\t\t</span>\n\t\t\t\t\t\t<span class="gstore-shipping-calculator__result-value">${destinationLabel||"-"}</span>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t`;this.resultContainer.html(html).addClass("is-visible")}showError(message){this.errorContainer.html('<i class="fa-solid fa-exclamation-circle" aria-hidden="true"></i> '+message).addClass("is-visible")}clearResult(){this.resultContainer.removeClass("is-visible").html("")}clearError(){this.errorContainer.removeClass("is-visible").html("")}}function initProductPage(){const $calculator=$(".gstore-shipping-calculator");if($calculator.length){$calculator.each(function(){new ShippingCalculator(this,{context:"single_product"})})}}function initCheckout(){let $calculator=$(".gstore-shipping-calculator");if(!$calculator.length){const $shippingSection=$(".woocommerce-shipping-fields, .woocommerce-shipping-methods");if($shippingSection.length){const calculatorHtml=`\n\t\t\t\t\t<div class="gstore-shipping-calculator gstore-shipping-calculator--checkout">\n\t\t\t\t\t\t<h3 class="gstore-shipping-calculator__title">\n\t\t\t\t\t\t\t<i class="fa-solid fa-calculator" aria-hidden="true"></i>\n\t\t\t\t\t\t\tCalcular Frete\n\t\t\t\t\t\t</h3>\n\t\t\t\t\t\t<div class="gstore-shipping-calculator__form">\n\t\t\t\t\t\t\t<input \n\t\t\t\t\t\t\t\ttype="text" \n\t\t\t\t\t\t\t\tclass="gstore-shipping-calculator__cep" \n\t\t\t\t\t\t\t\tplaceholder="00000-000"\n\t\t\t\t\t\t\t\tmaxlength="9"\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t<button type="button" class="gstore-shipping-calculator__button">\n\t\t\t\t\t\t\t\t<i class="fa-solid fa-truck" aria-hidden="true"></i>\n\t\t\t\t\t\t\t\tCalcular frete\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div class="gstore-shipping-calculator__result"></div>\n\t\t\t\t\t\t<div class="gstore-shipping-calculator__error"></div>\n\t\t\t\t\t</div>\n\t\t\t\t`;$shippingSection.before(calculatorHtml);$calculator=$(".gstore-shipping-calculator")}}if($calculator.length){$calculator.each(function(){new ShippingCalculator(this)})}$(document.body).on("updated_checkout",function(){const $billingPostcode=$("#billing_postcode");if($billingPostcode.length&&$billingPostcode.val()){const cep=$billingPostcode.val().replace(/\D/g,"");if(cep.length===8){$calculator.find(".gstore-shipping-calculator__cep").val(cep.replace(/(\d{5})(\d{3})/,"$1-$2"))}}});const $billingPostcode=$("#billing_postcode");if($billingPostcode.length){let checkoutCepTimeout;$billingPostcode.on("blur",function(){const cep=$(this).val().replace(/\D/g,"");if(cep.length===8&&$calculator.length){clearTimeout(checkoutCepTimeout);checkoutCepTimeout=setTimeout(function(){$calculator.find(".gstore-shipping-calculator__cep").val(cep.replace(/(\d{5})(\d{3})/,"$1-$2"));$calculator.find(".gstore-shipping-calculator__button").trigger("click")},500)}})}}function initCart(){const $calculator=$(".gstore-shipping-calculator");if($calculator.length){$calculator.each(function(){new ShippingCalculator(this)})}}$(document).ready(function(){if($("body").hasClass("single-product")){initProductPage()}if($("body").hasClass("woocommerce-cart")){return}})})(jQuery);
